window.VisualizationTools.anychart=function(element,json,callback){loadScript('https://cdn.anychart.com/releases/8.3.0/js/anychart-bundle.min.js').then(function(){window.anychart.fromJson(json.data).container(element).draw();window.resizeToShowContents(element);$(element).find('svg').each(function(idx,elt){$(elt).height($(elt.parentNode).height())});callback(element,element.childNodes[0])}).catch(function(error){console.error('Could not load anychart:',error)})}